{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello आपको fully automatic double die थाली machine की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "automatic"
    },
    {
      "i": 2,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 6,
      "speaker": "bot",
      "text": "मैं देख पा रही हूं आपको automation grade fully automatic ही चाहिए ना?"
    },
    {
      "i": 7,
      "speaker": "caller",
      "text": "ये जैसे की कितने तक मिल सकती है?"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "आप इसकी price seller से discuss कर सकते हैं।"
    },
    {
      "i": 9,
      "speaker": "bot",
      "text": "वो आपको best rates देंगे।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "अभी बस ये बता दीजिए कि automation grade fully automatic ही चाहिए ना?"
    },
    {
      "i": 11,
      "speaker": "caller",
      "text": "हाँ ये ये पूछ रहे हैं जैसे कि जो बनाते हैं machine से।"
    },
    {
      "i": 12,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "अब machine technology के बारे में बात कर लेते हैं।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "आपको hydraulic चाहिए, crank या कुछ और?"
    },
    {
      "i": 15,
      "speaker": "caller",
      "text": "ये नहीं पूछ रहे हैं।"
    },
    {
      "i": 16,
      "speaker": "bot",
      "text": "कोई बात नहीं क्या आप बता सकते हैं कि आपको machine technology में क्या prefer करेंगे hydraulic crank या कोई और?"
    },
    {
      "i": 17,
      "speaker": "caller",
      "text": "आपको तो करना होगा seller."
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "और कोई बात कर"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "और कोई बात कर सकता है?"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "बस कुछ details चाहिए ताकि मैं आपको सही seller से connect कर सकूं।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "आप अपनी city और state भी बता दीजिए please।"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "हाँ।"
    },
    {
      "i": 23,
      "speaker": "caller",
      "text": "उत्तर प्रदेश।"
    },
    {
      "i": 24,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 25,
      "speaker": "bot",
      "text": "पर आप Uttar Pradesh में किस city से बोल रहे हैं?"
    },
    {
      "i": 26,
      "speaker": "bot",
      "text": "Please बता दीजिए।"
    },
    {
      "i": 27,
      "speaker": "caller",
      "text": "बनारस बनारस।"
    },
    {
      "i": 28,
      "speaker": "bot",
      "text": "बना"
    },
    {
      "i": 29,
      "speaker": "bot",
      "text": "आप बनारस उत्तर प्रदेश से बोल रहे हैं ना?"
    }
  ]
}
